// Generated by node scripts/generate-consultation-links.ts; do not edit.
// 設定やサーバーに依存せず、CLIからも使える相談リンク。
function consultationLinks(consultationId, base) {
  const unavailable = (consultationUrlReason) => ({
    consultationId,
    consultationUrl: null,
    consultationUrlReason,
  });
  if (
    typeof consultationId !== 'string' ||
    !/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/.test(consultationId)
  )
    return unavailable('相談IDが受付画面の形式と一致しません。');
  if (base === undefined || base === null || base === '') return unavailable('受付の公開URLが設定されていません。');
  // eslint-disable-next-line no-control-regex -- 公開URL内の制御文字を拒否する。
  if (typeof base !== 'string' || !/^https?:\/\//i.test(base) || /[\s\\?#\u0000-\u001f\u007f]/.test(base))
    return unavailable('受付の公開URLを安全に使用できません。');
  try {
    const url = new URL(base);
    if (
      !['http:', 'https:'].includes(url.protocol) ||
      !url.hostname ||
      url.username ||
      url.password ||
      url.search ||
      url.hash ||
      base
        .slice(base.indexOf('://') + 3)
        .split('/')[0]
        .includes('@')
    )
      return unavailable('受付の公開URLを安全に使用できません。');
    url.hash = `/drafts/${consultationId}`;
    return { consultationId, consultationUrl: url.href, consultationUrlReason: null };
  } catch {
    return unavailable('受付の公開URLを安全に使用できません。');
  }
}

// 表示用hint、要対応のid/key、サーバーの自由文理由はリンクの材料にしない。
export function budgetStopped(value) {
  return (
    !!value?.consultationBudget?.stopped ||
    value?.caseKind === 'consultation_budget' ||
    value?.kind === 'consultation_budget'
  );
}

export function consultationOutput(value, context: { publicUrl?: string; base?: string } = {}) {
  const id = value?.kind === 'draft' || !value?.kind ? value?.id : (value?.draftId ?? value?.consultationId);
  const checked = consultationLinks(id, undefined);
  const safeId = checked.consultationUrlReason === '相談IDが受付画面の形式と一致しません。' ? null : id;
  if (!safeId) return { ...checked, consultationId: null };
  // 公開URLは完全なリンクとして対象IDまで検査する。認証query等は共通部品で拒否する。
  if (typeof value?.consultationUrl === 'string') {
    const suffix = `#/drafts/${safeId}`;
    if (value.consultationUrl.endsWith(suffix)) {
      const base = value.consultationUrl.slice(0, -suffix.length);
      const link = consultationLinks(safeId, base);
      if (link.consultationUrl === value.consultationUrl) return link;
    }
  }
  const local = consultationLinks(safeId, context.publicUrl);
  if (local.consultationUrl) return local;
  return consultationLinks(safeId, context.base);
}

export function stoppedConsultationText(value, context: { publicUrl?: string; base?: string } = {}) {
  const link = consultationOutput(value, context);
  return `相談ID: ${link.consultationId ?? '識別できません'}\n${
    link.consultationUrl
      ? `受付画面: ${link.consultationUrl}`
      : `受付画面URLを生成できません: ${link.consultationUrlReason}`
  }\n相談全体の上限で停止しています。受付画面の要対応から対象相談を開き、「上限を足して続行する」を選んでください。通常の返信・再試行・確定では続行できません。`;
}
// 要対応の次の担い手。I/O・実時刻を持たず、受付の記録を優先する。
import { attentionActor, attentionCaseKey, attentionActivity } from '../../shared/src/attention-split.generated.ts';

function activity(row) {
  const time = attentionActivity(row);
  return time === null ? null : new Date(time).toISOString();
}

const numberOf = (row) =>
  Number.isSafeInteger(row.number) ? row.number : Number.isSafeInteger(row.issue) ? row.issue : null;
const line = (value) =>
  String(value ?? '')
    .replace(/\s+/g, ' ')
    .trim();

function screenUrl(row, base) {
  const origin = new URL(base);
  origin.hash = '';
  origin.search = '';
  origin.username = '';
  origin.password = '';
  if (!['http:', 'https:'].includes(origin.protocol)) throw Error('受付URLは http または https を指定してください');
  let screen = row.screenPath;
  if (!screen) {
    screen =
      row.kind === 'draft'
        ? `#/drafts/${encodeURIComponent(row.id)}`
        : row.desk
          ? `#/issues/${row.desk}`
          : row.project && numberOf(row) !== null
            ? `#/issues/${row.project.split('/').map(encodeURIComponent).join('/')}/${numberOf(row)}`
            : `#/attention/${encodeURIComponent(row.key || row.id)}`;
  }
  // screenPath は同じ受付の画面へ限定し、別ホストや資格情報をURLへ持ち込まない。
  const target = new URL(screen, `${origin.href.replace(/\/$/, '')}/`);
  if (target.origin !== origin.origin || target.username || target.password)
    throw Error('screenPath は同じ受付の画面を指定してください');
  return target.href;
}

function fallback(row) {
  if (attentionActor(row) === 'system') return { nextActor: 'system', nextAction: '受付の自動処理の結果を待つ' };
  if (row.kind === 'attention') {
    return { nextActor: 'ai', nextAction: '記録を調べて対応を判断する' };
  }
  const actions = {
    issue: '原因を調べて再試行・修正依頼・返信する',
    stall: '止まりの原因を調べて対処する',
    full_test: 'main のテスト失敗を調べて修正を依頼する',
    usage_review: '利用量の記録を調べて見直す',
    close: '記録から判断して回答する',
    draft: '記録から判断して回答する',
  };
  return { nextActor: 'ai', nextAction: actions[row.kind] || '記録を調べて対応を判断する' };
}

export function nextStepForRow(row, base = 'http://127.0.0.1:8787/') {
  const computed = fallback(row);
  const nextActor = ['user', 'ai', 'system'].includes(row.nextActor) ? row.nextActor : computed.nextActor;
  const id =
    row.kind === 'issue'
      ? `issue:${row.project}#${numberOf(row)}`
      : row.kind === 'attention'
        ? `attention:${row.key}`
        : String(row.id ?? row.kind);
  return {
    nextActor,
    nextAction: line(row.nextAction) || computed.nextAction,
    evidence: { id: line(row.evidence?.id) || id, at: row.evidence?.at ?? activity(row) },
    ...(nextActor === 'user' ? { url: screenUrl(row, base) } : {}),
  };
}

function nextStepForCase(rows, base) {
  const steps = rows.map((row) => nextStepForRow(row, base));
  return (
    steps.find((step) => step.nextActor === 'ai') ||
    steps.find((step) => step.nextActor === 'user') ||
    steps[0] || { nextActor: 'system', nextAction: '受付の自動処理の結果を待つ', evidence: { id: 'empty', at: null } }
  );
}

// 旧公開名も同じ集約処理へ接続し、呼び出し側の互換性を保つ。

// summarizeDeskAttention と同じキーで元の行をまとめ、時刻や画面の指定を失わずに付加する。
export function attentionNextSteps(rows, cases, base) {
  const groups = new Map();
  rows.forEach((row, index) => {
    const key = attentionCaseKey(row, index);
    const group = groups.get(key) || [];
    group.push(row);
    groups.set(key, group);
  });
  const enriched = cases.map((entry) => ({
    ...entry,
    ...nextStepForCase(groups.get(entry.key) || [], base),
    ...(entry.waitExceeded ? { nextActor: 'ai', nextAction: '待ちの上限を超えた原因を調べて対処する' } : {}),
  }));
  const userActions = enriched
    .filter((entry) => entry.nextActor === 'user')
    .map((entry) => ({
      desk: entry.desk,
      project: entry.project,
      number: entry.number,
      nextAction: entry.nextAction,
      url: entry.url,
    }));
  return { cases: enriched, userActions };
}

export function nextStepSuffix(step) {
  const actor = { user: '利用者', ai: 'AI', system: '受付' }[step.nextActor];
  return ` 次: ${actor}: ${line(step.nextAction)}（根拠: ${line(step.evidence.id)} ${line(step.evidence.at) || '時刻不明'}）${step.nextActor === 'user' ? ` URL: ${step.url}` : ''}`;
}

// Stop フックが読む契約。必ず出力の最後の1行にし、接頭辞とカンマ区切りを変えない。
export function userNumbersLine(userActions) {
  const numbers = [
    ...new Set(userActions.flatMap((entry) => entry.members || [entry]).map((entry) => entry.desk).filter((desk) => Number.isSafeInteger(desk) && desk > 0)),
  ];
  return `利用者の操作が要る共通番号: ${numbers.length ? numbers.join(',') : 'なし'}`;
}
